            "units": [
              {
                "id": "p1-s1",
                "source": "The sea is never quite still.",
                "translation_vi": "Biển chẳng bao giờ hoàn toàn tĩnh lặng.",
                "precision": "sentence",
                "phrases": [
                  {
                    "source": "never quite still",
