            "units": [
              {
                "id": "p1-s1",
                "source": "Long before money existed, people still needed things they could not make themselves.",
                "translation_vi": "Từ rất lâu trước khi có tiền, con người vẫn cần những thứ họ không tự làm được.",
                "precision": "sentence",
                "phrases": [
                  {
                    "source": "Long before money existed",
                    "target": "Từ rất lâu trước khi có tiền"
                  },
                  {
                    "source": "could not make themselves",
                    "target": "không tự làm được"
                  }
                ]
              },
              {
                "id": "p1-s2",
                "source": "A farmer might have plenty of grain but no tools, while a metalworker had tools but no food.",
                "translation_vi": "Nông dân có thể dư ngũ cốc mà thiếu dụng cụ, còn thợ kim khí có dụng cụ nhưng thiếu thức ăn.",
                "precision": "sentence",
                "phrases": [
